TtsAsyncWaiter::TtsAsyncWaiter(
    Tts* proxy) : proxy_(proxy) {}

TtsAsyncWaiter::~TtsAsyncWaiter() = default;

void TtsAsyncWaiter::Speak(
    const std::string& utterance, TtsOptionsPtr options, TtsSpeakResultPtr* out_result) {
  base::RunLoop loop;
  proxy_->Speak(std::move(utterance),std::move(options),
      base::BindOnce(
          [](base::RunLoop* loop,
             TtsSpeakResultPtr* out_result
,
             TtsSpeakResultPtr result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

TtsSpeakResultPtr TtsAsyncWaiter::Speak(
    const std::string& utterance, TtsOptionsPtr options) {
  TtsSpeakResultPtr async_wait_result;
  Speak(std::move(utterance),std::move(options),&async_wait_result);
  return async_wait_result;
}

void TtsAsyncWaiter::IsSpeaking(
    bool* out_speaking) {
  base::RunLoop loop;
  proxy_->IsSpeaking(
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_speaking
,
             bool speaking) {*out_speaking = std::move(speaking);
            loop->Quit();
          },
          &loop,
          out_speaking));
  loop.Run();
}

bool TtsAsyncWaiter::IsSpeaking(
    ) {
  bool async_wait_result;
  IsSpeaking(&async_wait_result);
  return async_wait_result;
}

void TtsAsyncWaiter::GetVoices(
    std::vector<TtsVoicePtr>* out_voices) {
  base::RunLoop loop;
  proxy_->GetVoices(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<TtsVoicePtr>* out_voices
,
             std::vector<TtsVoicePtr> voices) {*out_voices = std::move(voices);
            loop->Quit();
          },
          &loop,
          out_voices));
  loop.Run();
}

std::vector<TtsVoicePtr> TtsAsyncWaiter::GetVoices(
    ) {
  std::vector<TtsVoicePtr> async_wait_result;
  GetVoices(&async_wait_result);
  return async_wait_result;
}






